import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0061 — Budget iniziale della console a 720 kB (M21)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0061-budget-iniziale-console-720.md","filePath":"adr/0061-budget-iniziale-console-720.md"}'),l={name:"adr/0061-budget-iniziale-console-720.md"};function d(n,e,c,r,s,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0061-—-budget-iniziale-della-console-a-720-kb-m21" tabindex="-1">ADR-0061 — Budget iniziale della console a 720 kB (M21) <a class="header-anchor" href="#adr-0061-—-budget-iniziale-della-console-a-720-kb-m21" aria-label="Permalink to &quot;ADR-0061 — Budget iniziale della console a 720 kB (M21)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-16, decisione dell&#39;owner); recepita in <code>Specifications.md</code> v1.7 (2026-11-16); implementata e rilasciata con la 1.7.2. Emenda <a href="./0020-performance-details.html">ADR-0020</a> (il limite iniziale della console)</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.7 (2026-11-16): §4.4 e Appendice C.4 (riga di ADR-0020)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-16</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§4.4 (budget di build della Web UI: «console iniziale ≤ 700 kB», <code>Specifications.md:1870</code>); Appendice C.4, riga di ADR-0020 (<code>:2001</code>); ADR-0020 (budget della Web UI, tabella «Console»: iniziale ≤ 700 kB, totale ≤ 1000 kB); ADR-0025; ADR-0029 (la console resta senza code splitting); <code>docs/web-ui.md</code> (tabella dei budget)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>sì, in un punto:</strong> §4.4 dice «console iniziale ≤ 700 kB» (<code>Specifications.md:1870</code>) e la riga di ADR-0020 in C.4 lo riassume; con questo ADR il limite è 720 kB. <strong>Emenda ADR-0020</strong> nel solo limite iniziale della console. Da recepire nello spec v1.7 (<a href="./../spec-v1.7-proposta.html"><code>spec-v1.7-proposta.md</code></a>). <strong>Decisione dell&#39;owner del 2026-11-16</strong></td></tr><tr><td><strong>Superfici</strong></td><td>console (prova: <code>task web-budget</code>, dentro <code>task ci</code>, che misura gli import statici di <code>src/main.tsx</code> con <code>checkBudget</code> di <code>web/scripts/esbuild.mjs</code>) · workbench, desktop e WebAssembly invariati</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Con il lavoro di M21 la console pesa <strong>701 kB</strong> iniziali (e totali) contro un limite di 700: <code>task ci</code> fallisce solo su <code>web-budget</code>. Le aggiunte sono funzioni richieste dall&#39;owner: la pagina pubblica «Sei uscito» e il logout completo (ADR-0058), il tooltip della percentuale rispetto alla quota, la gestione delle gemelle legacy nello ZIP dei vault privati (ADR-0059). Il margine prima di M21 era di pochi kB.</p><p>La console si compila <strong>in un solo file, senza code splitting</strong> (<code>splitting: false</code> in <code>web/scripts/esbuild.mjs</code>, ADR-0029, <code>docs/web-ui.md</code>): il suo <code>&lt;script&gt;</code> è coperto da SRI, mentre i chunk caricati da un import dinamico non lo sarebbero senza un&#39;import map. Per questo un <code>React.lazy</code> non riduce nulla: esbuild riporta il codice nel file principale (una prova sulla pagina «Sei uscito» ha dato 703 kB). La parte più grande evitabile è l&#39;export dei vault privati (circa 50 kB: <code>hash-wasm</code> per Argon2id, <code>packages/vaultcrypto-web</code>, <code>src/export/privateExport.ts</code>), che servirebbe solo all&#39;apertura del suo dialog.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><code>BUDGET.console.initialKB</code> passa da <strong>700 a 720 kB</strong> in <code>web/scripts/esbuild.mjs</code>. Il totale (1000 kB), il budget del workbench e quelli del WebAssembly non cambiano. La console resta un file unico coperto da SRI.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Togliere 2–3 kB dalle aggiunte di M21</strong> — scartata: il margine resterebbe quasi zero e il prossimo rilascio avrebbe lo stesso problema, senza un guadagno per l&#39;utente.</li><li><strong>Code splitting della console con import map SRI</strong> (come il workbench: <code>importMap: true</code> nella pagina, CSP di <code>services/cloud/web-embed/webembed.go</code> con gli hash dell&#39;import map, test di sicurezza e ADR-0029 da aggiornare), che sposterebbe l&#39;export privato in un chunk caricato all&#39;apertura del dialog e libererebbe circa 50 kB — scartata per la 1.7.2: tocca la CSP e la catena SRI, quindi va decisa e verificata a parte. È la strada da prendere se la console cresce ancora.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><code>task ci</code> torna verde con 701 kB su 720.</li><li>Il budget iniziale della console non è più lo stesso del desktop (ADR-0025, 700 kB): i due numeri restano indipendenti.</li><li>Allineati con l&#39;accettazione: ADR-0020 (revisione del 2026-11-16, che rinvia a questo ADR) e la tabella dei budget di <a href="./../web-ui.html"><code>docs/web-ui.md</code></a> (iniziale ≤ 720 kB). Lo spec cita il limite in §4.4: la v1.7 lo porta a 720 kB.</li></ul>',11)])])}const b=o(l,[["render",d]]);export{g as __pageData,b as default};
